import 'package:equatable/equatable.dart';import 'package:flutter_bloc/flutter_bloc.dart';import 'package:locallink/core/bloc/bloc_utils.dart';import 'package:locallink/core/models/account_restore.dart';import 'package:locallink/features/recovery/domain/account_restoration_repository_contract.dart';
final class AccountRestoreState extends Equatable{final AccountRestoreManifest? manifest;final bool loading,busy;final String? error;final String detail;const AccountRestoreState({this.manifest,this.loading=true,this.busy=false,this.error,this.detail=''});AccountRestoreState copyWith({AccountRestoreManifest? manifest,bool? loading,bool? busy,String? error,bool clearError=false,String? detail})=>AccountRestoreState(manifest:manifest??this.manifest,loading:loading??this.loading,busy:busy??this.busy,error:clearError?null:(error??this.error),detail:detail??this.detail);@override List<Object?>get props=>[manifest,loading,busy,error,detail];}
final class AccountRestoreBloc extends Cubit<AccountRestoreState>{final AccountRestorationRepositoryContract service;AccountRestoreBloc(this.service):super(const AccountRestoreState());AccountRestoreManifest? get manifest=>state.manifest;bool get loading=>state.loading;bool get busy=>state.busy;String? get error=>state.error;String get detail=>state.detail;Future<void> load()async{emit(state.copyWith(loading:true,clearError:true));try{emit(state.copyWith(manifest:await service.loadManifest(),loading:false));}catch(e){emit(state.copyWith(error:cleanBlocError(e),loading:false));}}Future<bool> createBackup(String passphrase)async{if(state.busy)return false;emit(state.copyWith(busy:true,clearError:true,detail:'Encrypting historical identity keys locally…'));try{await service.createEncryptedCryptoBackup(passphrase:passphrase);await load();return true;}catch(e){emit(state.copyWith(error:cleanBlocError(e)));return false;}finally{emit(state.copyWith(busy:false,detail:''));}}Future<bool> restore({String? passphrase})async{if(state.busy)return false;emit(state.copyWith(busy:true,clearError:true,detail:'Starting restore…'));try{await service.restoreAccountData(cryptoBackupPassphrase:passphrase,onProgress:(p)=>emit(state.copyWith(detail:p.detail)));await load();return true;}catch(e){emit(state.copyWith(error:cleanBlocError(e)));return false;}finally{emit(state.copyWith(busy:false,detail:''));}}}
